#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20};

    // Safe access
    std::cout << v.at(1) << "\n";

    // Unchecked access (O(1))
    std::cout << v[0] << "\n";

    // Accessing index 5 (size is 2) via operator[]
    // v[5]; // UNDEFINED BEHAVIOR

    // Accessing index 5 via at() (Throws exception)
    // try { v.at(5); } catch (const std::out_of_range& e) { /* handle */ }
}
